-- AI-generated summary of all reviews for a product.
-- Run after 20261116000000_create_products.sql.

alter table public.products
  add column if not exists ai_summary text,
  add column if not exists ai_summary_updated_at timestamptz;

comment on column public.products.ai_summary is
  'Short summary of all reviews, generated by the product-summary agent.';

comment on column public.products.ai_summary_updated_at is
  'When the AI summary was last generated.';
